import type { Page } from "@playwright/test";
import meta from "./meta.json";
import results from "./results.json";
import rows from "./rows.json";
import tools from "./tools.json";

// Fixtures were generated by the real Python engine (build_case(1, 0) + run_tool).
type Result = (typeof results)[keyof typeof results];
const COSTS: Record<string, number> = Object.fromEntries(tools.map((t) => [t.id, t.cost]));

export const CASE_ID = meta.case_id;
export const FRAUDSTER = "E4";

/** A tiny in-memory backend: budget, free cached re-runs, 409 when broke, paged rows. */
export async function mockCase(page: Page, { budget = meta.budget } = {}) {
  let left = budget;
  // The Next.js dev-tools badge (dev only) sits over the phone tab bar: hide it in tests.
  await page.addInitScript(() => {
    document.addEventListener("DOMContentLoaded", () => {
      const style = document.createElement("style");
      style.textContent = "nextjs-portal{display:none!important}";
      document.head.appendChild(style);
    });
  });
  const cache = new Map<string, Result>();

  await page.route(`**/api/cases/${CASE_ID}`, (route) =>
    route.fulfill({ json: { ...meta, budget_left: left } }),
  );
  await page.route("**/api/tools?*", (route) => route.fulfill({ json: tools }));
  await page.route(`**/api/cases/${CASE_ID}/tools/*`, async (route) => {
    const toolId = route.request().url().split("/").pop()!;
    const params = route.request().postDataJSON()?.params ?? {};
    const key = `${toolId}:${JSON.stringify(params)}`;
    const hit = cache.get(key);
    if (hit) return route.fulfill({ json: { ...hit, cost_charged: 0, budget_left: left } });
    const base = results[toolId as keyof typeof results];
    if (!base) return route.fulfill({ status: 403, json: { detail: "Locked" } });
    if (COSTS[toolId] > left) return route.fulfill({ status: 409, json: { detail: "Out of budget" } });
    left -= COSTS[toolId];
    const result = { ...base, params, result_id: `${base.result_id}-${cache.size}`, budget_left: left };
    cache.set(key, result);
    return route.fulfill({ json: result });
  });
  await page.route(`**/api/cases/${CASE_ID}/rows?*`, (route) => {
    const url = new URL(route.request().url());
    const offset = Number(url.searchParams.get("offset") ?? 0);
    const limit = Number(url.searchParams.get("limit") ?? 200);
    return route.fulfill({ json: { rows: rows.rows.slice(offset, offset + limit), total: rows.total } });
  });
}
